 				);
 			});

+			it("should retry writing files that fail with EMFILE or ENFILE", async () => {
+				const fileCount = 50;
+				const maxOpenFiles = 10;
+				const written = new Map();
+				let openFiles = 0;
+				let emfileErrors = 0;
+
+				// simulates a process that can only have a limited number of files open at once
+				const writeFile = sinon.spy(async (filePath, output) => {
+					if (openFiles >= maxOpenFiles) {
+						emfileErrors++;
+
+						const error = new Error(
+							`${emfileErrors % 2 ? "EMFILE" : "ENFILE"}: too many open files, open '${filePath}'`,
+						);
+
+						error.code = emfileErrors % 2 ? "EMFILE" : "ENFILE";
+						throw error;
+					}
+
+					openFiles++;
+					try {
+						await new Promise(resolve => {
+							setTimeout(resolve, 5);
+						});
+						written.set(filePath, output);
+					} finally {
+						openFiles--;
+					}
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": { writeFile },
+					},
+				);
+
+				const results = Array.from({ length: fileCount }, (_, i) => ({
+					filePath: path.resolve(`file_${i}.js`),
+					output: `output ${i}`,
+				}));
+
+				await localESLint.outputFixes(results);
+
+				assert(
+					emfileErrors > 0,
+					"The test should have hit the open file limit.",
+				);
+				assert.strictEqual(written.size, fileCount);
+				results.forEach(({ filePath, output }) => {
+					assert.strictEqual(written.get(filePath), output);
+				});
+			});
+
+			it("should not retry writing files that fail with other errors", async () => {
+				const error = new Error("EACCES: permission denied");
+
+				error.code = "EACCES";
+
+				const writeFile = sinon.spy(() => Promise.reject(error));
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": { writeFile },
+					},
+				);
+
+				await assert.rejects(
+					() =>
+						localESLint.outputFixes([
+							{
+								filePath: path.resolve("foo.js"),
+								output: "bar",
+							},
+						]),
+					error,
+				);
+				assert.strictEqual(writeFile.callCount, 1);
+			});
